<template>
    <div class="view-page kw-page">
        <header class="view-head kw-header"><div><RouterLink class="ext-back" to="/kb">返回知识库</RouterLink><h1 class="view-title">知识工作台</h1><p class="view-subtitle">把笔记、资料、流程和关联放到同一个工作区</p></div><div class="kw-row"><RouterLink class="btn" to="/kb/sops">SOP 清单</RouterLink><button id="kw-refresh" class="btn" :disabled="loading||busy" @click="refreshAll">刷新资料</button></div></header>
        <p v-if="error" class="workshop-error" role="alert">{{ error }}</p><p v-if="notice" class="workshop-success" role="status">{{ notice }}</p><p v-if="loading" role="status">正在读取知识库…</p><p v-if="state.truncated" class="workshop-note">当前关系/属性工作集最多2000篇、扫描正文8MiB，关系可能不完整；原知识库仍可搜索全部文档。</p>
        <nav class="kw-navigation" aria-label="工作台功能"><button v-for="item in sections" :key="item.id" class="btn btn-sm" :class="{'is-active':section===item.id}" :aria-pressed="section===item.id" @click="chooseSection(item.id)">{{ item.label }}</button></nav>
        <div class="kw-layout">
            <aside class="kw-sidebar" aria-label="工作台笔记导航"><label>快速切换 <kbd>Ctrl+K</kbd><input id="kw-search" ref="searchInput" v-model="search" class="input" type="search" placeholder="搜索笔记标题、路径或属性…" /></label><div class="kw-row"><button id="kw-new" class="btn btn-primary btn-sm" :disabled="busy" @click="createNote()">新建笔记</button><button id="kw-daily" class="btn btn-sm" :disabled="busy" @click="daily">每日笔记</button></div><label>新建/每日笔记使用模板<select v-model="templateId" class="input"><option value="">空白笔记</option><option v-for="item in templates" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><details v-if="bookmarks.length" open class="kw-details"><summary>书签</summary><button v-for="id in bookmarks" :key="id" class="kw-link" @click="openNote(id)">{{ state.notes.find(n=>n.id===id)?.title || `失效笔记 #${id}` }}</button></details><p class="kw-muted">{{ filteredNotes.length }}篇匹配 · 当前显示前200篇</p><ul class="kw-note-list"><li v-for="note in filteredNotes.slice(0,200)" :key="note.id"><button class="kw-note-link" :class="{'is-active':activeId===note.id}" :data-note-id="note.id" @click="openNote(note.id)"><strong>{{ note.title }}</strong><span>{{ note.path }}</span></button></li></ul><p v-if="!filteredNotes.length" class="kw-empty">没有匹配笔记。</p></aside>
            <main class="kw-main">
                <template v-if="section==='notes'"><div class="kw-tabs" role="tablist" aria-label="已打开笔记"><div v-for="id in tabs" :key="id" class="kw-tab"><button role="tab" class="btn btn-sm" :aria-selected="activeId===id" :class="{'is-active':activeId===id}" @click="openNote(id)">{{ state.notes.find(n=>n.id===id)?.title||`笔记#${id}` }}</button><button class="btn btn-sm" :aria-label="`关闭笔记${state.notes.find(n=>n.id===id)?.title||id}`" @click="closeTab(id)"><svg class="icon icon-sm" viewBox="0 0 24 24" aria-hidden="true"><path d="m6 6 12 12M6 18 18 6" /></svg></button></div></div>
                    <div class="kw-row kw-split-controls"><label><input v-model="split" type="checkbox" @click="split&&!paneRight?.canLeave()&&$event.preventDefault()" /> 分屏阅读与编辑</label><select v-if="split" v-model="secondaryId" class="input" aria-label="右侧笔记" @change="changeSecondary"><option :value="null">选择右侧笔记…</option><option v-for="note in state.notes" :key="note.id" :value="note.id">{{ note.title }}</option></select></div>
                    <div class="kw-panes" :class="{'is-split':split}"><KbNotePane ref="paneLeft" :id="activeId" :anchor="anchor" :notes="state.notes" :entries="state.entries" @open="openNote" @changed="refresh" @bookmark="bookmark" @template="fromNote" /><KbNotePane v-if="split" ref="paneRight" :id="secondaryId" secondary :notes="state.notes" :entries="state.entries" @open="openRight" @changed="refresh" @bookmark="bookmark" @template="fromNote" /></div>
                </template>
                <KbDatabase v-else-if="section==='database'" ref="sectionRef" :notes="state.notes" :entries="state.entries" @open="openNote" @changed="refresh" @create="createNote" />
                <KbKnowledgeMap v-else-if="['graph','canvas'].includes(section)" :key="section" ref="sectionRef" :kind="section" :notes="state.notes" :entries="state.entries" :edges="state.edges" :current-id="activeId" @open="openNote" @changed="refresh" />
                <KbLibrary v-else-if="['template','block','action'].includes(section)" :key="section" ref="sectionRef" :kind="section" :seed="seed" :entries="state.entries" :notes="state.notes" :current-id="activeId" @open="openNote" @changed="refresh" @create="createNote" />
                <section v-else-if="section==='workspace'" class="kw-workspaces"><h2>书签与工作区</h2><p class="kw-muted">具名保存已打开笔记、左右分屏和书签。内容保存在工具箱电脑，局域网访问者可见；当前没有账号隔离。</p><label>已保存工作区<select v-model="workspaceId" class="input" @change="workspaceName=workspace?.name||'我的工作区'"><option value="">新建工作区</option><option v-for="item in workspaces" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>名称<input v-model="workspaceName" class="input" maxlength="80" /></label><div class="kw-row"><button class="btn btn-primary" :disabled="busy" @click="saveWorkspace()">保存当前布局</button><button class="btn" :disabled="busy||!workspace" @click="restoreWorkspace">打开此工作区</button><button class="btn btn-danger" :disabled="busy||!workspace" @click="removeWorkspace">删除工作区</button></div><h3>当前书签</h3><div v-for="id in bookmarks" :key="id" class="kw-row"><button class="kw-link" @click="openNote(id)">{{ state.notes.find(n=>n.id===id)?.title||`失效笔记 #${id}` }}</button><button class="btn btn-sm" :disabled="busy" @click="bookmark(id)">移除书签</button></div><p class="kw-muted">在笔记工具栏点击“书签”可加入或移除此工作区的书签。</p></section>
                <KbTransfer v-else-if="section==='transfer'" ref="sectionRef" @changed="refresh" @open="openNote" />
            </main>
        </div>
        <details class="kw-details kw-help"><summary>帮助与整理建议</summary><p>推荐“页面目录 → 资料库类型 → 属性与标签 → 双向链接 → SOP模板”逐层整理。正文继续使用 Markdown；在这里编辑的笔记也能从原知识库查看。页面模板和资料库模板共用，画布连接表示整理关系，不会自动改写正文链接。</p><p>工作台自动化只响应工作台中的保存动作。版本历史自动保留最近20次标题/正文，总量50MiB后轮换较早记录；长期保留请做全量备份。关系图、块嵌入和同步块在工作台阅读中显示。</p></details>
    </div>
</template>
<script setup>
import { ref,computed,onMounted,onBeforeUnmount,nextTick } from 'vue';
import { useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate } from 'vue-router';
import { kbApi } from '../api/knowledge-workbench-client.js';
import { localDay } from '../utils/knowledge-workbench.js';
import KbNotePane from '../components/knowledge/KbNotePane.vue';
import KbDatabase from '../components/knowledge/KbDatabase.vue';
import KbKnowledgeMap from '../components/knowledge/KbKnowledgeMap.vue';
import KbLibrary from '../components/knowledge/KbLibrary.vue';
import KbTransfer from '../components/knowledge/KbTransfer.vue';
const route=useRoute(),router=useRouter(),state=ref({notes:[],entries:[],edges:[],unresolved:[],truncated:false}),section=ref('notes'),search=ref(''),searchInput=ref(null),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),activeId=ref(null),secondaryId=ref(null),previousSecondary=ref(null),split=ref(false),tabs=ref([]),templateId=ref(''),anchor=ref(''),seed=ref(null),workspaceId=ref(''),workspaceName=ref('我的工作区'),paneLeft=ref(null),paneRight=ref(null),sectionRef=ref(null);
const sections=[{id:'notes',label:'笔记'},{id:'database',label:'资料库'},{id:'graph',label:'关系图谱'},{id:'canvas',label:'知识画布'},{id:'template',label:'模板'},{id:'block',label:'同步块'},{id:'workspace',label:'工作区'},{id:'action',label:'按钮与自动化'},{id:'transfer',label:'剪藏与迁移'}];
const templates=computed(()=>state.value.entries.filter(e=>e.kind==='template')),workspaces=computed(()=>state.value.entries.filter(e=>e.kind==='workspace')),workspace=computed(()=>workspaces.value.find(e=>e.id===workspaceId.value)),bookmarks=computed(()=>workspace.value?.data.bookmarks||[]),filteredNotes=computed(()=>{const query=search.value.trim().toLocaleLowerCase();return state.value.notes.filter(n=>!query||(n.path+' '+JSON.stringify(n.meta.values)).toLocaleLowerCase().includes(query));});
let alive=true,listController,mutationController=new AbortController(),generation=0;
async function refresh(){listController?.abort();listController=new AbortController();const own=++generation;loading.value=true;error.value='';try{const result=await kbApi.state(listController.signal);if(!alive||own!==generation)return;state.value=result;if(!workspaceId.value&&workspaces.value.length){workspaceId.value=workspaces.value[0].id;workspaceName.value=workspace.value.name;}window.dispatchEvent(new Event('kb-changed'));}catch(failure){if(alive&&own===generation&&!listController.signal.aborted)error.value=failure.message;}finally{if(alive&&own===generation)loading.value=false;}}
async function refreshAll(){if(!canLeave())return;await refresh();await Promise.all([paneLeft.value?.reload(),paneRight.value?.reload()]);}
function canLeave(){return !busy.value&&[paneLeft.value,paneRight.value,sectionRef.value].every(pane=>!pane?.canLeave||pane.canLeave());}
function chooseSection(id){if(id===section.value)return;if(!canLeave())return;section.value=id;seed.value=null;}
function openNote(id,targetAnchor=''){if(!Number.isSafeInteger(Number(id))||Number(id)<1)return;if(id!==activeId.value||section.value!=='notes'){if(!canLeave())return;}activeId.value=Number(id);if(!tabs.value.includes(activeId.value))tabs.value.push(activeId.value);if(tabs.value.length>30)tabs.value.shift();section.value='notes';anchor.value=targetAnchor;seed.value=null;}
function openRight(id){if(!paneRight.value?.canLeave())return;secondaryId.value=Number(id);previousSecondary.value=Number(id);}
function changeSecondary(){if(paneRight.value&&!paneRight.value.canLeave())secondaryId.value=previousSecondary.value;else previousSecondary.value=secondaryId.value;}
function closeTab(id){if(id===activeId.value&&!paneLeft.value?.canLeave())return;tabs.value=tabs.value.filter(item=>item!==id);if(activeId.value===id)activeId.value=tabs.value.at(-1)||null;}
async function operation(task){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const result=await task(mutationController.signal);if(alive)return result;}catch(failure){if(alive&&!mutationController.signal.aborted)error.value=failure.message;}finally{if(alive)busy.value=false;}}
async function createNote(template='',database=''){if(!canLeave())return;const result=await operation(signal=>kbApi.create({...(template||templateId.value?{templateId:template||templateId.value}:{}),...(database?{databaseId:database}:{})},signal));if(result){await refresh();openNote(result.id);}}
async function daily(){if(!canLeave())return;const result=await operation(signal=>kbApi.create({daily:true,day:localDay(),...(templateId.value?{templateId:templateId.value}:{})},signal));if(result){await refresh();openNote(result.id);notice.value=result.reused?'打开已有每日笔记':'已创建今日笔记';}}
function layout(){return{tabs:[...tabs.value],active:activeId.value,secondary:secondaryId.value,split:split.value,bookmarks:[...bookmarks.value]};}
async function saveWorkspace(data=layout()){const item=workspace.value;const result=await operation(signal=>kbApi.saveEntry({...(item?{id:item.id,version:item.version}:{}),kind:'workspace',name:workspaceName.value,data},signal));if(result){workspaceId.value=result.id;await refresh();notice.value='工作区已保存';}}
async function bookmark(id){const data=layout();data.bookmarks=data.bookmarks.includes(id)?data.bookmarks.filter(value=>value!==id):[...data.bookmarks,id];await saveWorkspace(data);}
function restoreWorkspace(){if(!canLeave())return;const data=workspace.value.data,exists=id=>state.value.notes.some(n=>n.id===id);tabs.value=data.tabs.filter(exists);activeId.value=exists(data.active)?data.active:tabs.value[0]||null;secondaryId.value=exists(data.secondary)?data.secondary:null;previousSecondary.value=secondaryId.value;split.value=data.split;section.value='notes';}
async function removeWorkspace(){if(!confirm('永久删除此工作区？笔记和画布保留。'))return;const result=await operation(signal=>kbApi.remove(workspace.value,signal));if(result){workspaceId.value='';await refresh();}}
function fromNote(note){if(!canLeave())return;section.value='template';seed.value={kind:'template',name:note.title+' 模板',data:{title:note.title,content:note.content_md,databaseId:note.meta.databaseId,values:JSON.parse(JSON.stringify(note.meta.values))}};}
function keyboard(event){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchInput.value?.focus();searchInput.value?.select();}}
function beforeUnload(event){if(busy.value||paneLeft.value?.hasUnsaved?.()||paneRight.value?.hasUnsaved?.()||sectionRef.value?.dirty||sectionRef.value?.hasUnsaved?.()){event.preventDefault();event.returnValue='';}}
onBeforeRouteLeave(()=>canLeave());onBeforeRouteUpdate((to)=>{if(to.query.note&&Number(to.query.note)!==activeId.value){if(!canLeave())return false;openNote(Number(to.query.note),String(to.query.anchor||''));}});
onMounted(async()=>{window.addEventListener('keydown',keyboard);window.addEventListener('beforeunload',beforeUnload);await refresh();if(alive){const requested=Number(route.query.note);openNote(state.value.notes.some(n=>n.id===requested)?requested:state.value.notes[0]?.id||null,String(route.query.anchor||''));await nextTick();}});
onBeforeUnmount(()=>{alive=false;generation++;listController?.abort();mutationController.abort();window.removeEventListener('keydown',keyboard);window.removeEventListener('beforeunload',beforeUnload);});
</script>
